          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./wasm/flows_jj.wasm": "./wasm/flows_jj.wasm",
      "./internal/*": null,
      "./*/index": null,
      "./Jj": {
        "import": {
          "types": "./dist/esm/Jj.d.ts",
          "default": "./dist/esm/Jj.js"
        },
        "require": {
          "types": "./dist/cjs/Jj.d.ts",
          "default": "./dist/cjs/Jj.js"
        }
      },
      "./browser/BrowserJj": {
        "import": {
          "types": "./dist/esm/browser/BrowserJj.d.ts",
          "default": "./dist/esm/browser/BrowserJj.js"
        },
        "require": {
          "types": "./dist/cjs/browser/BrowserJj.d.ts",
          "default": "./dist/cjs/browser/BrowserJj.js"
        }
      },
      "./browser/WasiFs": {
