      "./browser/WasiPreview1": {
        "import": {
          "types": "./dist/esm/browser/WasiPreview1.d.ts",
          "default": "./dist/esm/browser/WasiPreview1.js"
        },
        "require": {
          "types": "./dist/cjs/browser/WasiPreview1.d.ts",
          "default": "./dist/cjs/browser/WasiPreview1.js"
        }
      },
      "./bun/BunJj": {
        "import": {
          "types": "./dist/esm/bun/BunJj.d.ts",
          "default": "./dist/esm/bun/BunJj.js"
        },
        "require": {
          "types": "./dist/cjs/bun/BunJj.d.ts",
