        "import": {
          "types": "./dist/esm/node/NodeJj.d.ts",
          "default": "./dist/esm/node/NodeJj.js"
        },
        "require": {
          "types": "./dist/cjs/node/NodeJj.d.ts",
          "default": "./dist/cjs/node/NodeJj.js"
        }
      },
      "./node/resolveJjBinary": {
        "import": {
          "types": "./dist/esm/node/resolveJjBinary.d.ts",
          "default": "./dist/esm/node/resolveJjBinary.js"
        },
        "require": {
          "types": "./dist/cjs/node/resolveJjBinary.d.ts",
